for case,projects in changes.items():
 vals=[]
 for name in ['temporal','temporal-agent']:
  r=projects[name];v=r['incremental_seconds'];whole='—' if case=='route-add' else f"{r.get('whole_operation_seconds',v):.3f}";vals.extend([f'{v:.3f}',whole])
 lines.append('| '+case+' | '+' | '.join(vals)+' |')
lines += ['', 'All 26 final changed-input/lifecycle checks pass complete publication equality against independent forced computation. Source include/region invalidation and corrupted transient repair were additionally established at T8. Route fixtures verify retirement of owned HTML/download/sitemap/LLM products and authored tags; arbitrary hardcoded source references are not promised to rewrite themselves. Shared navigation/runtime changes still fan out broadly.','']
lines += ['','Initial T7 changed-input costs remain visible (single runs, seconds; rendered initial body fixtures changed HTML only, whereas final fixtures coordinate companion views):','', '| Case | Initial authored | Final authored | Initial rendered | Final rendered |','| --- | ---: | ---: | ---: | ---: |']
